package com.example.nailsalon.entity; import jakarta.persistence.*; import jakarta.validation.constraints.*;
@Entity public class Payment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotNull private Long appointmentId; @DecimalMin("0.01") private double amount; @NotBlank private String method; @NotBlank private String status="PAID"; public Payment(){} public Long getId(){return id;} public Long getAppointmentId(){return appointmentId;} public void setAppointmentId(Long v){appointmentId=v;} public double getAmount(){return amount;} public void setAmount(double v){amount=v;} public String getMethod(){return method;} public void setMethod(String v){method=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
